{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1724;--glass:rgba(255,255,255,0.06);--glass-2:rgba(255,255,255,0.04);--accent:#E3B7A0;--muted:#b8c4cf;--card:#0b1220}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,Arial,Helvetica,sans-serif;color:#e6eef6;background:linear-gradient(180deg,#061020 0%, #071427 40%);-webkit-font-smoothing:antialiased}
    /* unique svg pattern as data URI background */
    body::before{content:'';position:fixed;inset:0;opacity:0.09;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='400' height='400'><defs><linearGradient id='g' x1='0' x2='1'><stop stop-color='%23E3B7A0' offset='0'/><stop stop-color='%239EC5B0' offset='1'/></linearGradient></defs><g fill='none' stroke='rgba(255,255,255,0.06)' stroke-width='1'><path d='M0 100 C100 0 300 0 400 100' stroke='url(%23g)'/></g></svg>");background-repeat:repeat;mix-blend-mode:screen}
    .wrap{max-width:1100px;margin:40px auto;padding:28px}
    nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#9EC5B0);display:flex;align-items:center;justify-content:center;font-weight:700;color:#08202a}
    .site-title{font-size:18px;font-weight:600}
    .nav-links{display:flex;gap:12px}
    .nav-links a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:10px}
    .nav-links a:hover{background:var(--glass);color:#fff}
    .glass-card{background:linear-gradient(180deg,var(--glass),var(--glass-2));border-radius:14px;padding:22px;backdrop-filter:blur(8px);box-shadow:0 6px 18px rgba(6,10,18,0.6);border:1px solid rgba(255,255,255,0.04)}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:18px;align-items:center}
    h1{margin:0;font-size:28px}
    p.lead{color:var(--muted);margin-top:8px}
    .cta-row{margin-top:14px;display:flex;gap:12px;align-items:center}
    .btn{background:linear-gradient(90deg,var(--accent),#9EC5B0);color:#08202a;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:600}
    .secondary{background:transparent;border:1px solid rgba(255,255,255,0.06);padding:9px 12px;border-radius:10px;color:var(--muted);text-decoration:none}

    /* layout pieces */
    .two-col{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .section-title{font-weight:700;margin-bottom:8px}
    .mood-box{display:flex;gap:8px;flex-wrap:wrap}
    .mood-btn{padding:8px 10px;border-radius:10px;background:rgba(255,255,255,0.02);color:var(--muted);border:1px solid rgba(255,255,255,0.02);cursor:pointer}
    .mood-btn.active{background:linear-gradient(90deg,var(--accent),#9EC5B0);color:#08202a}

    /* aroma wheel */
    .wheel{display:flex;flex-direction:column;align-items:center;gap:12px}
    .wheel svg{width:280px;height:280px}
    .note-legend{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
    .legend-item{padding:6px 10px;border-radius:10px;background:rgba(255,255,255,0.02);font-size:13px;color:var(--muted)}
    .tooltip{min-height:64px;padding:10px;border-radius:10px;background:rgba(255,255,255,0.02);color:var(--muted)}

    .benefits{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
    .benefit{padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.02)}
    .process{display:flex;flex-direction:column;gap:8px}
    .process-step{display:flex;gap:12px;align-items:flex-start}
    .testimonials{display:flex;flex-direction:column;gap:8px}
    .testimonial{padding:12px;border-radius:10px;background:rgba(255,255,255,0.02)}
    .faq{margin-top:12px}
    .faq-item{margin-bottom:8px}
    footer{margin-top:24px;text-align:center;color:var(--muted);font-size:13px}

    @media (max-width:900px){.hero{grid-template-columns:1fr;}.two-col{grid-template-columns:1fr}.logo{width:48px;height:48px}}
  </style>
</head>
<body>
  <div class="wrap">
    <nav>
      <div class="brand">
        <div class="logo">A</div>
        <div>
          <div class="site-title">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <div class="nav-links">
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends</a>
        <a href="shop.html">Boutique</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Our Story</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach</a>
      </div>
    </nav>

    <div class="glass-card hero">
      <div>
        <h1>Seasonal and Everyday Aromatherapy Support</h1>
        <p class="lead">Personalized scent guidance and ready-made options that may support your day-to-day mood and routines. We emphasize safety, gentle dilution, and clear usage notes.</p>
        <div class="cta-row">
          <a id="primaryCta" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="secondary" href="book.html">Reserve a consult</a>
        </div>
        <div style="margin-top:12px;color:var(--muted);font-size:13px">Phone: {{PHONE}} · Email: {{EMAIL}}</div>
      </div>
      <div style="display:flex;flex-direction:column;gap:12px">
        <div class="glass-card" style="flex:1">
          <div class="section-title">Mood-to-Method selector</div>
          <p style="color:var(--muted);margin:6px 0">Pick how you feel and we’ll suggest an approachable delivery style plus a brief note on dilution and safety.</p>
          <div class="mood-box" id="moodButtons">
            <button class="mood-btn" data-mood="calm">Calm</button>
            <button class="mood-btn" data-mood="focus">Focus</button>
            <button class="mood-btn" data-mood="sleep">Sleep</button>
            <button class="mood-btn" data-mood="uplift">Uplift</button>
            <button class="mood-btn" data-mood="ground">Ground</button>
          </div>
          <div style="margin-top:10px">
            <strong>Recommended:</strong> <span id="methodLabel">Choose a mood</span>
            <div style="font-size:12px;color:var(--muted);margin-top:6px">Note: follow dilution guidelines and do a patch test. Not medical advice — aromatherapy may support wellbeing.</div>
          </div>
        </div>

        <div class="glass-card" style="padding:12px">
          <div class="section-title">Testimonials</div>
          <div class="testimonials">
            <div class="testimonial">"The blend I got for evening rituals has become a quiet anchor." — a client in {{CITY}}</div>
            <div class="testimonial">"Simple, useful suggestions and clear safety notes made it easy to try." — local workshop attendee</div>
          </div>
        </div>
      </div>
    </div>

    <div class="two-col">
      <div class="glass-card">
        <div class="section-title">How scent may help</div>
        <div class="benefits">
          <div class="benefit"><strong>Micro-practices</strong><div style="color:var(--muted);margin-top:6px">Short inhalations or roll-on rituals that fit into daily routines.</div></div>
          <div class="benefit"><strong>At-home blends</strong><div style="color:var(--muted);margin-top:6px">Pre-mixed options and custom blends with dilution guidance.</div></div>
          <div class="benefit"><strong>Portable tools</strong><div style="color:var(--muted);margin-top:6px">Inhalers, roll-ons, and mini diffusers for on-the-go use.</div></div>
          <div class="benefit"><strong>Safety-first notes</strong><div style="color:var(--muted);margin-top:6px">Clear instructions around pets, pregnancy, and patch testing.</div></div>
        </div>

        <div style="margin-top:14px" class="section-title">Aroma wheel</div>
        <div class="wheel">
          <svg id="aromaWheel" viewBox="0 0 400 400" aria-hidden="true">
            <defs>
              <linearGradient id="gradT" x1="0" x2="1"><stop offset="0" stop-color="#FDE6D6"/><stop offset="1" stop-color="#E3B7A0"/></linearGradient>
              <linearGradient id="gradM" x1="0" x2="1"><stop offset="0" stop-color="#EEF6F2"/><stop offset="1" stop-color="#9EC5B0"/></linearGradient>
              <linearGradient id="gradB" x1="0" x2="1"><stop offset="0" stop-color="#DDECF8"/><stop offset="1" stop-color="#9BB7D8"/></linearGradient>
            </defs>
            <g transform="translate(200,200)">
              <circle r="120" fill="url(#gradT)" data-zone="top" class="zone"/>
              <circle r="80" fill="url(#gradM)" data-zone="middle" class="zone"/>
              <circle r="40" fill="url(#gradB)" data-zone="base" class="zone"/>
              <text x="0" y="-135" text-anchor="middle" font-size="12" fill="#08202a">Top notes</text>
              <text x="0" y="-60" text-anchor="middle" font-size="12" fill="#08202a">Middle</text>
              <text x="0" y="12" text-anchor="middle" font-size="12" fill="#08202a">Base notes</text>
            </g>
          </svg>
          <div class="note-legend" id="legend">
            <div class="legend-item" data-note="bergamot">Bergamot (top)</div>
            <div class="legend-item" data-note="lavender">Lavender (middle)</div>
            <div class="legend-item" data-note="vetiver">Vetiver (base)</div>
            <div class="legend-item" data-note="lemon">Lemon (top)</div>
            <div class="legend-item" data-note="rose">Rose (middle)</div>
            <div class="legend-item" data-note="patchouli">Patchouli (base)</div>
          </div>
          <div class="tooltip" id="wheelTooltip">Hover a segment or legend to see a gentle description.</div>
        </div>

      </div>

      <aside class="glass-card">
        <div class="section-title">Our approach</div>
        <div class="process">
          <div class="process-step"><strong>1.</strong><div style="color:var(--muted);">A brief check-in to hear what you want to try.</div></div>
          <div class="process-step"><strong>2.</strong><div style="color:var(--muted);">A custom suggestion with dilution and a patch-test plan.</div></div>
          <div class="process-step"><strong>3.</strong><div style="color:var(--muted);">A follow-up note and optional retail add-ons for the home.</div></div>
        </div>

        <div style="margin-top:12px">
          <div class="section-title">Quick links</div>
          <div style="display:flex;flex-direction:column;gap:8px;margin-top:8px">
            <a class="secondary" href="blends.html">Explore signature blends</a>
            <a class="secondary" href="shop.html">Shop the boutique</a>
            <a class="secondary" href="book.html">Book a tailored session</a>
          </div>
        </div>
      </aside>
    </div>

    <div class="glass-card faq">
      <div class="section-title">FAQ & safety notes</div>
      <div class="faq-item"><strong>Do I need to dilute oils?</strong><div style="color:var(--muted);margin-top:6px">Yes. We include recommended dilutions with every custom or retail blend and suggest a patch test before skin use.</div></div>
      <div class="faq-item"><strong>Are aromatics safe around pets?</strong><div style="color:var(--muted);margin-top:6px">Some essential oils may not be suitable for animals. We provide pet-safe guidance on request and include alternatives when needed.</div></div>
      <div class="faq-item"><strong>Pregnancy or health conditions?</strong><div style="color:var(--muted);margin-top:6px">Consult a qualified health provider for medical advice. Our notes avoid medical claims; aromatherapy may support comfort but is not a substitute for medical care.</div></div>
      <div class="faq-item"><strong>Patch test?</strong><div style="color:var(--muted);margin-top:6px">Apply a small diluted amount to the forearm and wait 24 hours. Stop use if irritation occurs.</div></div>
    </div>

    <div class="glass-card" style="margin-top:12px;display:flex;justify-content:space-between;align-items:center">
      <div>
        <div style="font-weight:700">Ready for a small scent experiment?</div>
        <div style="color:var(--muted);font-size:13px;margin-top:6px">Select a mood above to tailor the next step.</div>
      </div>
      <div style="display:flex;gap:8px">
        <a id="primaryCtaFooter" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="secondary" href="contact.html">Questions</a>
      </div>
    </div>

    <footer>© {{BUSINESS_NAME}} · {{CITY}}, {{STATE}} · <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a></footer>
  </div>

  <script>
    (function(){
      // Mood-to-Method mapping
      const map = {
        calm: {method:'Roll-on ritual',cta:'Try Calm Roll-on'},
        focus: {method:'Diffuser bursts',cta:'Explore Focus Diffuser'},
        sleep: {method:'Pillow mist',cta:'Shop Sleep Mist'},
        uplift: {method:'Inhaler or spritz',cta:'Find Uplift Tools'},
        ground: {method:'Patch or oil blend',cta:'Order Grounding Blend'}
      };
      const btns = document.querySelectorAll('.mood-btn');
      const methodLabel = document.getElementById('methodLabel');
      const primary = document.getElementById('primaryCta');
      const primaryFooter = document.getElementById('primaryCtaFooter');
      btns.forEach(b=>b.addEventListener('click',()=>{
        btns.forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        const m = b.dataset.mood;
        methodLabel.textContent = map[m].method + ' — gentle dilution advised.';
        primary.textContent = map[m].cta + ' · ' + '{{PRIMARY_CTA_LABEL}}';
        primaryFooter.textContent = primary.textContent;
      }));

      // Aroma wheel hover logic
      const wheel = document.getElementById('aromaWheel');
      const tooltip = document.getElementById('wheelTooltip');
      const noteData = {
        bergamot:'Bergamot (top) — bright, citrusy. Use small bursts; photosensitive oils require care.',
        lemon:'Lemon (top) — fresh, enlivening. Avoid direct sun on skin after use.',
        lavender:'Lavender (middle) — floral, balancing. Commonly included for gentle support.',
        rose:'Rose (middle) — soft, aromatic. Use sparingly; fragrant and grounding in blends.',
        vetiver:'Vetiver (base) — earth-forward, anchoring. Often used in small percentages.',
        patchouli:'Patchouli (base) — deep, long-lasting. Strong potency; dilute for skin.'
      };
      // hover for legend items
      document.querySelectorAll('.legend-item').forEach(li=>{
        li.addEventListener('mouseenter',()=>{tooltip.textContent = noteData[li.dataset.note];});
        li.addEventListener('mouseleave',()=>{tooltip.textContent = 'Hover a segment or legend to see a gentle description.'});
      });
      // wheel region hover (simple radial detection)
      wheel.addEventListener('mousemove',e=>{
        const rect = wheel.getBoundingClientRect();
        const cx = rect.left + rect.width/2; const cy = rect.top + rect.height/2;
        const dx = e.clientX - cx; const dy = e.clientY - cy; const r = Math.sqrt(dx*dx+dy*dy);
        if(r<40) tooltip.textContent = 'Base notes: deep, long-lasting anchors like vetiver or patchouli.';
        else if(r<80) tooltip.textContent = 'Middle notes: body of the scent — florals and herbs.';
        else if(r<120) tooltip.textContent = 'Top notes: first impression — citrus, light herbs.';
        else tooltip.textContent = 'Hover a segment or legend to see a gentle description.';
      });
      wheel.addEventListener('mouseleave',()=>{tooltip.textContent = 'Hover a segment or legend to see a gentle description.'});

    })();
  </script>
</body>
</html>"} 
