<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Blends — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071427;--glass:rgba(255,255,255,0.05);--accent:#B7E3CF;--muted:#bfd2cf}
    body{margin:0;font-family:Inter,system-ui,Arial;color:#eef5f8;background:linear-gradient(180deg,#02111a,#041822);-webkit-font-smoothing:antialiased}
    .container{max-width:1000px;margin:36px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    .nav{display:flex;gap:10px}
    .nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    .nav a:hover{background:rgba(255,255,255,0.03)}
    .glass{background:linear-gradient(180deg,var(--glass),rgba(255,255,255,0.01));padding:18px;border-radius:12px;margin-top:18px;border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0}
    .intro{color:var(--muted);margin-top:8px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:16px;margin-top:16px}
    .blend-list{display:flex;flex-direction:column;gap:12px}
    .blend{padding:12px;border-radius:10px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.02)}
    .badge{font-size:12px;padding:6px 8px;border-radius:8px;background:rgba(255,255,255,0.02);display:inline-block;color:var(--muted)}
    .wheel-box{display:flex;flex-direction:column;align-items:center;gap:10px}
    .legend{display:flex;gap:6px;flex-wrap:wrap}
    .legend div{background:rgba(255,255,255,0.02);padding:6px 10px;border-radius:8px;color:var(--muted)}
    .faq{margin-top:12px}
    .cta{display:flex;gap:8px;justify-content:space-between;align-items:center;margin-top:12px}
    .btn{background:linear-gradient(90deg,var(--accent),#9EC5B0);padding:10px 14px;border-radius:10px;color:#04201a;text-decoration:none;font-weight:600}
