<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Boutique — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#06121a;--glass:rgba(255,255,255,0.03);--card:#081822;--accent:#EFD4C8;--muted:#aebcc6}
    body{margin:0;font-family:Inter,system-ui,Arial;background:linear-gradient(180deg,#031017,#061423);color:#eef7f7}
    .frame{max-width:1100px;margin:36px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    .nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
    .hero{margin-top:16px;padding:18px;border-radius:12px;background:linear-gradient(180deg,var(--glass),rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.02)}
    .products{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}
    .product{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.02)}
    .price{font-weight:700;color:var(--accent)}
    .small{font-size:13px;color:var(--muted)}
    .sidebar{margin-left:12px}
    .flex{display:flex}
    .mood-row{display:flex;gap:8px;margin-top:10px}
    .mood-btn{padding:8px 10px;border-radius:10px;background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);cursor:pointer}
    .mood-btn.active{background:linear-gradient(90deg,var(--accent),#9EC5B0);color:#081821}
    .cta{margin-top:12px}
    @media(max-width:900px){.products{grid-template-columns:1fr}.sidebar{margin-left:0;margin-top:12px}}
  </style>
</head>
<body>
  <div class="frame">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,#EFD4C8,#9EC5B0);display:flex;align-items:center;justify-content:center;color:#04121a;font-weight:700">S</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div class="small">Retail items and add-ons with safety notes</div>
        </div>
      </div>
      <nav class="nav">
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends</a>
        <a href="shop.html">Boutique</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Story</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <section class="hero">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:12px">
        <div>
          <h2 style="margin:0">Boutique: ready-made and refill items</h2>
          <div class="small" style="margin-top:6px">Kits, inhalers, travel roll-ons, and refill concentrates. Each product lists suggested dilutions and patch-test reminders.</div>
        </div>
        <div style="text-align:right">
          <div class="small">Questions? <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a></div>
          <div style="margin-top:8px"><a class="small" href="book.html">Schedule a blend session</a></div>
        </div>
      </div>
    </section>

    <div style="display:flex;gap:12px;margin-top:12px">
      <div style="flex:1">
        <div class="products">
          <div class="product">
            <div style="font-weight:700">Mini Calm Roll-on</div>
            <div class="small">Lavender & sweet marjoram infused in fractionated coconut oil. 10ml.</div>
            <div class="price">$18</div>
            <div style="margin-top:8px"><button class="add" data-sku="calm-10">Add to cart</button></div>
          </div>
          <div class="product">
            <div style="font-weight:700">Diffuser Blend — Focus</div>
            <div class="small">Lemon, rosemary. 10ml diffuser concentrate.</div>
            <div class="price">$14</div>
            <div style="margin-top:8px"><button class="add" data-sku="focus-10">Add to cart</button></div>
          </div>
          <div class="product">
            <div style="font-weight:700">Inhaler set (3)</div>
            <div class="small">Three inhalers with curated blends. Portable inhalation tools.</div>
            <div class="price">$22</div>
            <div style="margin-top:8px"><button class="add" data-sku="inhaler-3">Add to cart</button></div>
          </div>
        </div>

        <div class="glass" style="margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.02)">
          <div style="font-weight:700">Retail add-on: refill concentrate</div>
          <div class="small" style="margin-top:6px">Concentrates for those who've had a session — follow included dilution instructions when mixing for topical use.</div>
        </div>
      </div>

      <aside class="sidebar" style="width:320px">
        <div class="glass" style="padding:12px">
          <div style="font-weight:700">Mood picker</div>
          <p class="small" style="margin-top:6px">Selected mood updates a suggested product approach and CTA phrasing.</p>
          <div class="mood-row" id="moods">
            <button class="mood-btn" data-mood="calm">Calm</button>
            <button class="mood-btn" data-mood="focus">Focus</button>
            <button class="mood-btn" data-mood="sleep">Sleep</button>
          </div>
          <div id="suggest" style="margin-top:10px;color:var(--muted)">Pick a mood to see a suggestion.</div>
          <div class="cta" style="margin-top:12px">
            <a id="shopCta" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="glass" style="margin-top:12px;padding:12px">
          <div style="font-weight:700">Aroma notes preview</div>
          <svg id="miniWheel" viewBox="0 0 240 240" style="width:200px;height:200px;margin-top:8px">
            <defs>
              <linearGradient id="g1"><stop offset="0" stop-color="#FDE6D6"/><stop offset="1" stop-color="#E3B7A0"/></linearGradient>
              <linearGradient id="g2"><stop offset="0" stop-color="#E8F7F0"/><stop offset="1" stop-color="#B7E3CF"/></linearGradient>
              <linearGradient id="g3"><stop offset="0" stop-color="#E8F3FF"/><stop offset="1" stop-color="#9BB7D8"/></linearGradient>
            </defs>
            <g transform="translate(120,120)">
              <circle r="90" fill="url(#g1)"/>
              <circle r="50" fill="url(#g2)"/>
              <circle r="20" fill="url(#g3)"/>
              <text x="0" y="-100" text-anchor="middle" font-size="11" fill="#04121a">Top</text>
              <text x="0" y="-30" text-anchor="middle" font-size="11" fill="#04121a">Middle</text>
              <text x="0" y="20" text-anchor="middle" font-size="11" fill="#04121a">Base</text>
            </g>
          </svg>
          <div class="small" style="margin-top:8px;color:var(--muted)">Hover product items for sample note breakdowns.</div>
        </div>

        <div class="glass" style="margin-top:12px;padding:12px">
          <div style="font-weight:700">Safety & notes</div>
          <div class="small" style="margin-top:6px;color:var(--muted)">All products include dilution guidance and a patch-test reminder. If pregnant or caring for pets, consult our safety notes or ask before purchase.</div>
        </div>
      </aside>
    </div>

    <footer style="margin-top:18px;color:var(--muted);font-size:13px">© {{BUSINESS_NAME}} · <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a> · {{CITY}}, {{STATE}}</footer>
  </div>

  <script>
    (function(){
      // simplistic cart placeholder
      document.querySelectorAll('.add').forEach(b=>b.addEventListener('click',()=>{
        alert('Added ' + b.dataset.sku + ' to cart (demo)');
      }));

      // Mood-to-Method updates CTA
      const moodButtons = document.querySelectorAll('.mood-btn');
      const suggest = document.getElementById('suggest');
      const shopCta = document.getElementById('shopCta');
      const map = {calm:{text:'Calm roll-ons or inhalers may suit short pauses.',ctaText:'Shop Calm Tools'},focus:{text:'Diffuser concentrates for intermittent cycles.',ctaText:'Shop Focus Mixes'},sleep:{text:'Pillow mists and gentle night blends.',ctaText:'Shop Sleep Aids'}};
      moodButtons.forEach(btn=>btn.addEventListener('click',()=>{
        moodButtons.forEach(x=>x.classList.remove('active'));
        btn.classList.add('active');
        const m = btn.dataset.mood;
        suggest.textContent = map[m].text + ' Dilution and patch-test info included.';
        shopCta.textContent = map[m].ctaText + ' · ' + '{{PRIMARY_CTA_LABEL}}';
        localStorage.setItem('preferredMood',m);
      }));

      // Product hover to show notes (demo mapping)
      const noteMap = { 'calm-10':'Top: Bergamot · Middle: Lavender · Base: Vetiver', 'focus-10':'Top: Lemon · Middle: Rosemary · Base: Cedar', 'inhaler-3':'Top: Citrus trio · Middle: Floral · Base: Resinous hints' };
      document.querySelectorAll('.product').forEach(p=>{
        p.addEventListener('mouseenter',()=>{
          const sku = p.querySelector('button.add')?.dataset.sku;
          if(sku && noteMap[sku]) p.style.boxShadow = '0 8px 26px rgba(0,0,0,0.5)';
        });
        p.addEventListener('mouseleave',()=>{p.style.boxShadow='none'});
      });

    })();
  </script>
</body>
</html>"} 
